/* -------- CNN / RNN / LSTM -------- */
static double havier_rand(int fi,int fo){return ai_xavier_weight(g_runtime_vm,fi,fo);}
static Value ai_conv2d(VM*vm,int n,Value*a){(void)vm;if(n<2||n>4||a[0].t!=VARR||a[1].t!=VARR)return vn();Value x=a[0],k=a[1];size_t H=x.u.a->n,W=0,KH=k.u.a->n,KW=0;if(!H||!KH||x.u.a->v[0].t!=VARR||k.u.a->v[0].t!=VARR)return vn();W=x.u.a->v[0].u.a->n;KW=k.u.a->v[0].u.a->n;if(!W||!KW||H>2048||W>2048||KH>1024||KW>1024)return vn();for(size_t i=0;i<H;i++)if(x.u.a->v[i].t!=VARR||x.u.a->v[i].u.a->n!=W)return vn();for(size_t i=0;i<KH;i++)if(k.u.a->v[i].t!=VARR||k.u.a->v[i].u.a->n!=KW)return vn();int stride=n>=3&&a[2].t==VINT?(int)a[2].u.i:1,pad=n>=4&&a[3].t==VINT?(int)a[3].u.i:0;if(stride<1||stride>16||pad<0||pad>512)return vn();if(H+2*(size_t)pad<KH||W+2*(size_t)pad<KW)return va();size_t OH=(H+2*(size_t)pad-KH)/(size_t)stride+1,OW=(W+2*(size_t)pad-KW)/(size_t)stride+1;if(OH*OW>4000000ULL)return vn();Value out=va();for(size_t oy=0;oy<OH;oy++){Value row=va();for(size_t ox=0;ox<OW;ox++){double s=0;for(size_t ky=0;ky<KH;ky++){int iy=(int)(oy*(size_t)stride+ky)-(int)pad;if(iy<0||(size_t)iy>=H)continue;for(size_t kx=0;kx<KW;kx++){int ix=(int)(ox*(size_t)stride+kx)-(int)pad;if(ix<0||(size_t)ix>=W)continue;if(!isnum(x.u.a->v[iy].u.a->v[ix])||!isnum(k.u.a->v[ky].u.a->v[kx]))return vn();s+=dn(x.u.a->v[iy].u.a->v[ix])*dn(k.u.a->v[ky].u.a->v[kx]);}}ap(row.u.a,vf(s));}ap(out.u.a,row);}return out;}
static Value ai_rnn(VM*vm,int n,Value*a){(void)vm;if(n!=2||a[0].t!=VINT||a[1].t!=VINT)return vn();int in=(int)a[0].u.i,h=(int)a[1].u.i;if(in<1||in>128||h<1||h>256)return vn();Value o=vsobj();stput(o.u.st,"kind",vs("rnn"));stput(o.u.st,"input",vi(in));stput(o.u.st,"hidden",vi(h));Value W=va(),U=va(),b=va();for(int j=0;j<h;j++){Value r=va();for(int i=0;i<in;i++)ap(r.u.a,vf(havier_rand(in,h)));ap(W.u.a,r);Value u=va();for(int z=0;z<h;z++)ap(u.u.a,vf(havier_rand(h,h)));ap(U.u.a,u);ap(b.u.a,vf(0));}stput(o.u.st,"Wxh",W);stput(o.u.st,"Whh",U);stput(o.u.st,"b",b);return o;}
static Value ai_rnn_forward(VM*vm,int n,Value*a){(void)vm;if(n!=2||a[0].t!=VSTRUCT||a[1].t!=VARR)return vn();Value m=a[0],seq=a[1];Value iv=stget(m.u.st,"input"),hv=stget(m.u.st,"hidden"),Wx=stget(m.u.st,"Wxh"),Wh=stget(m.u.st,"Whh"),b=stget(m.u.st,"b");if(iv.t!=VINT||hv.t!=VINT||Wx.t!=VARR||Wh.t!=VARR||b.t!=VARR)return vn();int in=(int)iv.u.i,h=(int)hv.u.i;Value state=va();for(int j=0;j<h;j++)ap(state.u.a,vf(0));Value out=va();for(size_t t=0;t<seq.u.a->n;t++){Value x=seq.u.a->v[t];if(x.t!=VARR||x.u.a->n!=(size_t)in)return vn();Value ns=va();for(int j=0;j<h;j++){double z=dn(b.u.a->v[j]);Value wr=Wx.u.a->v[j],ur=Wh.u.a->v[j];for(int i=0;i<in;i++)z+=dn(wr.u.a->v[i])*dn(x.u.a->v[i]);for(int q=0;q<h;q++)z+=dn(ur.u.a->v[q])*dn(state.u.a->v[q]);ap(ns.u.a,vf(tanh(z)));}state=ns;ap(out.u.a,state);}return out;}
static Value ai_lstm(VM*vm,int n,Value*a){(void)vm;if(n!=2||a[0].t!=VINT||a[1].t!=VINT)return vn();int in=(int)a[0].u.i,h=(int)a[1].u.i;if(in<1||in>128||h<1||h>256)return vn();Value o=vsobj();stput(o.u.st,"kind",vs("lstm"));stput(o.u.st,"input",vi(in));stput(o.u.st,"hidden",vi(h));Value W=va(),U=va(),b=va();for(int q=0;q<4*h;q++){Value rw=va(),ru=va();for(int i=0;i<in;i++)ap(rw.u.a,vf(havier_rand(in,h)));for(int j=0;j<h;j++)ap(ru.u.a,vf(havier_rand(h,h)));ap(W.u.a,rw);ap(U.u.a,ru);ap(b.u.a,vf(0));}stput(o.u.st,"W",W);stput(o.u.st,"U",U);stput(o.u.st,"b",b);return o;}
static Value ai_lstm_forward(VM*vm,int n,Value*a){(void)vm;if(n!=2||a[0].t!=VSTRUCT||a[1].t!=VARR)return vn();Value m=a[0],seq=a[1];Value iv=stget(m.u.st,"input"),hv=stget(m.u.st,"hidden"),W=stget(m.u.st,"W"),U=stget(m.u.st,"U"),b=stget(m.u.st,"b");if(iv.t!=VINT||hv.t!=VINT||W.t!=VARR||U.t!=VARR||b.t!=VARR)return vn();int in=(int)iv.u.i,h=(int)hv.u.i;Value H=va(),C=va();for(int j=0;j<h;j++){ap(H.u.a,vf(0));ap(C.u.a,vf(0));}Value out=va();for(size_t t=0;t<seq.u.a->n;t++){Value x=seq.u.a->v[t];if(x.t!=VARR||x.u.a->n!=(size_t)in)return vn();Value nh=va(),nc=va();for(int j=0;j<h;j++){double z[4]={dn(b.u.a->v[j]),dn(b.u.a->v[h+j]),dn(b.u.a->v[2*h+j]),dn(b.u.a->v[3*h+j])};for(int i=0;i<in;i++){double xv=dn(x.u.a->v[i]);z[0]+=dn(W.u.a->v[j].u.a->v[i])*xv;z[1]+=dn(W.u.a->v[h+j].u.a->v[i])*xv;z[2]+=dn(W.u.a->v[2*h+j].u.a->v[i])*xv;z[3]+=dn(W.u.a->v[3*h+j].u.a->v[i])*xv;}for(int q=0;q<h;q++){double hvv=dn(H.u.a->v[q]);z[0]+=dn(U.u.a->v[j].u.a->v[q])*hvv;z[1]+=dn(U.u.a->v[h+j].u.a->v[q])*hvv;z[2]+=dn(U.u.a->v[2*h+j].u.a->v[q])*hvv;z[3]+=dn(U.u.a->v[3*h+j].u.a->v[q])*hvv;}double ig=1/(1+exp(-fmax(-60.0,fmin(60.0,z[0])))),fg=1/(1+exp(-fmax(-60.0,fmin(60.0,z[1])))),og=1/(1+exp(-fmax(-60.0,fmin(60.0,z[3])))),gg=tanh(z[2]);double cv=fg*dn(C.u.a->v[j])+ig*gg;ap(nc.u.a,vf(cv));ap(nh.u.a,vf(og*tanh(cv)));}H=nh;C=nc;ap(out.u.a,H);}return out;}

